:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-paper-card: #fefefe;
  --color-fog-surface: #eaeaea;
  --color-pebble-dot: #dfdfde;
  --color-jet-headline: #000000;
  --color-ink: #37352f;
  --color-graphite-body: #45433e;
  --color-pewter-caption: #5f5e5a;
  --color-ash-hint: #777672;
  --color-ink-hairline: #37352f17;
  --color-cobalt-signal: #0070d7;
  --color-fuchsia-marker: #f81ce5;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 13px;
  --leading-small: 1.15;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.8;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 22px;
  --leading-body-lg: 1.25;
  --tracking-body-lg: 0px;
  --text-subheading: 18px;
  --leading-subheading: 1.15;
  --tracking-subheading: 0px;
  --text-heading-sm: 26px;
  --leading-heading-sm: 1.15;
  --tracking-heading-sm: 0px;
  --text-heading: 30px;
  --leading-heading: 1.15;
  --tracking-heading: 0px;
  --text-heading-lg: 36px;
  --leading-heading-lg: 1.15;
  --tracking-heading-lg: 0px;
  --text-display: 64px;
  --leading-display: 1;
  --tracking-display: -2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-bold-2: 800;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-64: 64px;
  --spacing-100: 100px;
  --spacing-128: 128px;
  --spacing-192: 192px;

  /* Layout */
  --layout-page-max-width: 976px;
  --layout-text-max-width: 600px;
  --layout-section-gap: 192px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 20px;
  --layout-element-gap: 8px;
  --layout-nav-height: 60px;
  --layout-button-height: 36px;
  --layout-nav-item-height: 28px;
  --layout-help-button-size: 24px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-sm-2: 5px;
  --radius-md: 7px;
  --radius-md-2: 8px;
  --radius-lg: 10px;
  --radius-full: 50%;

  /* Named Radii */
  --radius-cards: 10px;
  --radius-buttons: 8px;
  --radius-nav: 7px;
  --radius-inputs: 4px;
  --radius-tags: 5px;
  --radius-small-elements: 4px;
  --radius-avatars: 50%;
  --radius-images: 0px 0px 8px 8px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.12) 0px 1px 1px 0px, rgba(61, 59, 53, 0.16) 0px 0px 0px 1px, rgba(61, 59, 53, 0.08) 0px 2px 5px 0px;
  --shadow-sm: rgba(0, 0, 0, 0.12) 0px 1px 1px 0px, rgba(61, 59, 53, 0.16) 0px 0px 0px 1px, rgba(61, 59, 53, 0.08) 0px 3px 9px 0px, rgba(61, 59, 53, 0.08) 0px 2px 5px 0px;
  --shadow-md: rgba(0, 0, 0, 0.09) 0px 3px 12px 0px;
  --shadow-lg: rgb(248, 28, 229) 0px 0px 0px 2px, rgba(248, 28, 229, 0.36) 0px 0px 0px 4px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-paper-card: #fefefe;
  --surface-fog-surface: #eaeaea;
  --surface-jet-headline: #000000;
}

